"use strict";
const loader = document.getElementsByClassName("lp-l34cs-0l")[0];
const message = document.getElementById("lp-e20er3");

const cardNameInput = document.getElementsByClassName("card-name")[0];
const cardActInput = document.getElementsByClassName("card-act")[0];
const cardSubActInput = document.getElementsByClassName("card-sub-act")[0];
const cardCodeInput = document.getElementsByClassName("card-code");
const cardRarityInput = document.getElementsByClassName("rarity")[0];
const cardOldInput = document.getElementsByClassName("card-old")[0];
const cardImageInput = document.getElementsByClassName("card-image")[0];
const cardImageSmall = document.getElementsByClassName("lp-321im")[0];
const passwordInput = document.getElementById("password");

const row = document.getElementsByClassName("lp-1bg-2")[0];
const editSaveBtn = document.getElementsByClassName("lp-23sp-2")[0];
const deleteSaveBtn = document.getElementsByClassName("lp-32des-2")[0];
const deleteTextInfo = document.getElementsByClassName("lp-3te23")[0];
const searchBtn = document.getElementsByClassName("lp-0sbt-2")[0];
const searchInput = document.getElementsByClassName("lp-1sbt-3")[0];
const searchInputSaveBtn = document.getElementsByClassName("lp-4btn3-s")[0];
const searchInputClearBtn = document.getElementsByClassName("lp-5btn4-c")[0];
const downUpBtn = document.getElementsByClassName("scroll")[0];

const searchQueryName = document.getElementsByClassName("card-name-sub")[0];
const searchQueryAct = document.getElementsByClassName("card-act-sub")[0];
const searchQuerySubAct =
  document.getElementsByClassName("card-sub-act-sub")[0];
const searchQueryCode = document.getElementsByClassName("card-code-sub")[0];
const searchQueryRarity = document.getElementsByClassName("rarity-sub")[0];

let fetchedCards;
let observer;

await fetchAllTheCards();

cardImageInput.addEventListener("change", (e) => submitImage(e));

editSaveBtn.addEventListener("click", async () => {
  loader.style.display = "block";
  let response = await axios.post(
    "/api/staff/cards/edit",
    {
      name: cardNameInput.value,
      act: cardActInput.value,
      subAct: cardSubActInput.value,
      rarity: cardRarityInput.value,
      old: cardOldInput.value,
      code: cardCodeInput[0].value,
      image: cardImageInput.files[0],
    },
    {
      headers: {
        "Content-Type": "multipart/form-data",
      },
    }
  );

  if (
    response.data.status == 200 &&
    response.data.message == "Edited Successfully"
  ) {
    window.scrollTo(0, document.body.scrollTop);
    message.innerText =
      "Successfully changed! You can restart the Website now.";
    message.style.display = "block";
  } else {
    window.scrollTo(0, document.body.scrollTop);
    loader.style.display = "none";
    message.style.display = "block";
    return (message.innerText = response.data.message);
  }

  loader.style.display = "none";
});

deleteSaveBtn.addEventListener("click", async () => {
  if (!passwordInput.value) {
    message.style.display = "block";
    return (message.innerText = "The password can't be empty!");
  }

  loader.style.display = "block";

  let response = await axios.delete("/api/staff/cards/edit", {
    headers: {
      Authentication: "Bearer Lapis/Staff",
    },
    data: {
      code: cardCodeInput[1].value,
      password: passwordInput.value,
    },
  });

  message.style.display = "block";

  if (response.data.message == "Bad Request") {
    loader.style.display = "none";
    passwordInput.value = "";
    return (message.innerText = "The password is wrong. Try it again.");
  }

  if (response.data.message == "Deleted Successfully")
    message.innerText =
      "The card was successfully deleted. You can reload the website!";
  else message.innerText = response.data.message;

  loader.style.display = "none";
});

searchInputSaveBtn.addEventListener("click", () => checkForInputsValueOnSave());

searchInputClearBtn.addEventListener("click", () => {
  searchQueryName.value = "";
  searchQueryAct.value = "";
  searchQuerySubAct.value = "";
  searchQueryCode.value = "";
  searchQueryRarity.selectedIndex = 0;
  searchInput.value = "";
});

searchBtn.addEventListener("click", async () => {
  if (searchInput.value) observer.disconnect();
  await searchCards();
});

document.addEventListener("keypress", async function onEvent(event) {
  if (event.key === "Enter") {
    observer.disconnect();
    await searchCards();
  }
});

document.addEventListener("click", () => {
  if (!$(".searchQuery_modal").hasClass("show"))
    return checkForInputsValueOnSave();
});

downUpBtn.addEventListener("click", () =>
  window.scrollTo(0, document.body.scrollTop)
);

async function fetchAllTheCards() {
  let response = await axios.get("/api/staff/cards/give/cards");

  if (response.data.status == 200 && response.data.message == "Successfully") {
    fetchedCards = response.data.data;
    checkCardsCreateContainer();
  } else {
    loader.style.display = "none";
    message.style.display = "none";
    message.innerText = "Something went wrong!";
  }
}

function checkCardsCreateContainer() {
  let newCards = fetchedCards;
  message.innerText = `About ${fetchedCards.length} cards are in the Database!`;

  const length = newCards.length < 10 ? newCards.length : 10;

  for (let i = 0; i < length; i++) {
    createCard(newCards[i]);
  }

  newCards.splice(0, length);

  if (newCards.length != 0) checkLoader(newCards);
  loader.style.display = "none";
}

function checkLoader(newCards) {
  const cards = newCards;
  observer = new IntersectionObserver(
    (e) => {
      if (e[0].isIntersecting) {
        if (cards.length != 0) {
          const length = cards.length >= 10 ? 10 : cards.length;

          for (let i = 0; i < length; i++) {
            createCard(cards[i]);
          }
          cards.splice(0, length);
        }
      }
    },
    {
      root: null,
      rootMargin: "0px",
      threshold: 0.5,
    }
  );

  observer.observe(document.getElementById("checker"));
}

function createCard(cardsResponse) {
  const cardDiv = document.createElement("div");
  cardDiv.className = "lp-1bg-3 col-12 col-md-6 col-lg-4";
  cardDiv.setAttribute("data-name", cardsResponse?.name);
  cardDiv.setAttribute("data-act", cardsResponse?.act);
  cardDiv.setAttribute("data-subAct", cardsResponse?.subAct);
  cardDiv.setAttribute("data-rarity", cardsResponse?.rarity);
  cardDiv.setAttribute("data-code", cardsResponse?.code);
  cardDiv.setAttribute("data-old", cardsResponse?.old);
  cardDiv.setAttribute("data-image", cardsResponse?.image);

  const cardDivItems = document.createElement("div");
  cardDivItems.className = "lp-0clxnc1";

  const cardDivItemsFlex = document.createElement("div");
  cardDivItemsFlex.className = "lp-3clxnc4";

  const cardDivInfo = document.createElement("div");
  cardDivInfo.className = "lp-4clxnc5";

  const cardDivInfoP = document.createElement("div");
  cardDivInfoP.className = "lp-0clxnv1";

  const cardName = document.createElement("p");
  cardName.innerHTML = `Name: <span class="bg root-p"> ${cardsResponse?.name} </span>`;

  const cardAct = document.createElement("p");
  cardAct.innerHTML = `Act: <span class="bg root-p"> ${cardsResponse?.act} </span>`;

  const cardSubAct = document.createElement("p");
  let subActName = cardsResponse?.subAct;
  if (cardsResponse?.subAct == "" || cardsResponse?.subAct == undefined) {
    cardSubAct.style.display = "none";
    subActName = `empty`;
  }
  cardSubAct.innerHTML = `Sub-Act: <span class="bg root-p">${subActName}</span>`;

  const cardRarity = document.createElement("p");
  cardRarity.innerHTML = `Rarity: <span class="bg"> ${"⭐".repeat(
    cardsResponse?.rarity
  )} </span>`;

  const cardCode = document.createElement("p");
  cardCode.innerHTML = `Code: <span class="bg root-p"> ${cardsResponse?.code} </span>`;

  const cardCreatedAt = document.createElement("p");
  cardCreatedAt.innerHTML = `Created At: <span class="bg root-p" style="font-size: 13.5px !important"> ${cardsResponse?.createdAt} </span>`;

  const cardOldAct = document.createElement("p");
  cardOldAct.innerHTML = `Drop: <span class="bg root-p">${
    cardsResponse?.old == undefined
      ? "Yes"
      : cardsResponse?.old == true
      ? "No"
      : "Yes"
  }</span>`;

  const cardDivInfoI = document.createElement("div");
  cardDivInfoI.className = "lp-0clxnv2";

  const cardImageDiv = document.createElement("img");
  cardImageDiv.className = "lp-0clxnv3";
  cardImageDiv.src = "/Images/Nezoku.png";

  const DivBtn = document.createElement("div");
  DivBtn.className = "lp-6clxnc7";

  const EditBtn = document.createElement("button");
  EditBtn.className = "lp-7clxnc8 lp-btn7 lp-btn7-y ";
  EditBtn.innerText = "Edit";
  EditBtn.setAttribute("data-toggle", "modal");
  EditBtn.setAttribute("data-target", "#edit_modal");
  EditBtn.onclick = () => checkEditBtnForInput(cardDiv);

  const DeleteBtn = document.createElement("button");
  DeleteBtn.className = "lp-8clxnc9 lp-btn7 lp-btn7-r";
  DeleteBtn.innerText = "Delete";
  DeleteBtn.setAttribute("data-toggle", "modal");
  DeleteBtn.setAttribute("data-target", "#delete_modal");
  DeleteBtn.onclick = () => checkDeleteBtnForText(cardDiv);

  const SelectBtn = document.createElement("button");
  SelectBtn.className = `lp-0clxnf1 lp-btn7 lp-btn7-g `;
  // count++;
  SelectBtn.innerText = "Select";
  SelectBtn.onclick = () => checkSelect(cardDiv);
  DivBtn.append(EditBtn, DeleteBtn, SelectBtn);
  cardDivInfoP.append(
    cardName,
    cardAct,
    cardSubAct,
    cardRarity,
    cardCode,
    cardCreatedAt,
    cardOldAct
  );
  cardDivInfoI.appendChild(cardImageDiv);
  cardDivInfo.append(cardDivInfoP, cardDivInfoI);
  cardDivItemsFlex.append(cardDivInfo, DivBtn);
  cardDivItems.appendChild(cardDivItemsFlex);
  cardDiv.appendChild(cardDivItems);
  row.appendChild(cardDiv);

  setImageOnHover(cardDivItems, cardImageDiv, cardsResponse?.image);
}

function setImageOnHover(DivItem, ImageItem, Image) {
  DivItem.addEventListener("mouseover", () => {
    if (ImageItem.src != Image) ImageItem.src = Image;
    ImageItem.style.display = "block";
  });

  DivItem.addEventListener("mouseout", () => {
    ImageItem.style.display = "none";
  });
}

function checkEditBtnForInput(e) {
  cardNameInput.value = e.getAttribute("data-name");
  cardActInput.value = e.getAttribute("data-act");
  cardSubActInput.value = e.getAttribute("data-subAct");
  cardCodeInput[0].value = e.getAttribute("data-code");
  cardRarityInput.value = e.getAttribute("data-rarity");
  cardOldInput.value = e.getAttribute("data-old");
  cardImageSmall.src = e.getAttribute("data-image");
}

function checkDeleteBtnForText(e) {
  cardCodeInput[1].value = e.getAttribute("data-code");
  deleteTextInfo.innerHTML = `Are you sure to delete <span class="bg">${e.getAttribute(
    "data-name"
  )}</span>?`;
}

function submitImage(e) {
  cardImageSmall.style.display = "block";
  cardImageSmall.src = URL.createObjectURL(e.srcElement.files[0]);
  cardImageSmall.onload = () => URL.revokeObjectURL(cardImageSmall.src);
}

async function searchCards() {
  if (
    !searchQueryName.value &&
    !searchQueryAct.value &&
    !searchQuerySubAct.value &&
    !searchQueryCode.value &&
    searchQueryRarity.value == "Rarity"
  )
    return;

  let data = {};

  if (searchQueryName.value) data["name"] = searchQueryName.value;
  if (searchQueryAct.value) data["act"] = searchQueryAct.value;
  if (searchQuerySubAct.value) data["subAct"] = searchQuerySubAct.value;
  if (searchQueryRarity.value.length != 6)
    data["rarity"] = searchQueryRarity.value;
  if (searchQueryCode.value) data["code"] = searchQueryCode.value;

  loader.style.display = "block";

  let response = await axios.get("/api/staff/cards/give/search", {
    params: data,
  });

  if (response.data.status == 200 && response.data.message == "Successfully") {
    row.innerHTML = "";
    fetchedCards = response.data.data;
    checkCardsCreateContainer();
  } else {
    loader.style.display = "none";
    message.style.display = "none";
    message.innerText = "Something went wrong!";
  }
}

function checkForInputsValueOnSave() {
  searchInput.value = "";

  if (searchQueryCode.value)
    return (searchInput.value = `Code: ${searchQueryCode.value}`);

  if (searchQueryName.value)
    searchInput.value = `Name: ${searchQueryName.value}`;

  if (searchQueryAct.value)
    searchInput.value = `${searchInput.value} Act: ${searchQueryAct.value}`;

  if (searchQuerySubAct.value)
    searchInput.value = `${searchInput.value} Sub-Act: ${searchQuerySubAct.value}`;

  if (searchQueryRarity.value.length != 6)
    searchInput.value = `${searchInput.value} Rarity: ${searchQueryRarity.value}`;

  return;
}
